from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.models import Subscription
from ledgerly.subscriptions import daily_rate
from ledgerly.errors import BillingError

def sub(price, days):
    return Subscription("s","c",price,days,datetime(2026,1,1,tzinfo=timezone.utc))

print(daily_rate(sub(Decimal("30.00"),30)))   # 1.00
print(daily_rate(sub(Decimal("10.00"),3)))    # 3.33
print(daily_rate(sub(Decimal("100.00"),7)))   # 14.29
print(daily_rate(sub(Decimal("0.05"),2)))     # 0.03 (half-even on 0.025 -> 0.02? check)
try:
    daily_rate(sub(Decimal("10.00"),0))
except BillingError as e:
    print("zero:", e.code)
try:
    daily_rate(sub(10.0,30))
except BillingError as e:
    print("float:", e.code)
EOF"}

